begin;

-- O catálogo pode ser público sem publicar um roteiro. A publicação do guia
-- continua controlada por guide_versions.status e por revisão humana.
alter table public.tutorials
  add column if not exists image_context_slug text;

update public.tutorials
set image_context_slug = slug
where image_context_slug is null;

alter table public.tutorials
  alter column image_context_slug set not null;

alter table public.tutorials
  drop constraint if exists tutorials_image_context_slug_check;
alter table public.tutorials
  add constraint tutorials_image_context_slug_check
  check (image_context_slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$');

alter table public.guide_versions
  add column if not exists public_for_upload boolean not null default false;

alter table public.steps
  add column if not exists editorial_key text;

alter table public.steps
  drop constraint if exists steps_editorial_key_check;
alter table public.steps
  add constraint steps_editorial_key_check check (
    editorial_key is null or (
      char_length(editorial_key) between 1 and 200
      and editorial_key ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
    )
  );

create unique index if not exists steps_guide_editorial_key_idx
  on public.steps(guide_version_id, editorial_key)
  where editorial_key is not null;

create temporary table guido_import_categories on commit drop as
select * from jsonb_to_recordset($json$[{"name":"Serviços financeiros","slug":"servicos-financeiros","description":"Orientações educativas sobre aplicativos financeiros."},{"name":"Comunicação","slug":"comunicacao","description":"Orientações educativas para mensagens, chamadas e contatos."},{"name":"Serviços públicos","slug":"servicos-publicos","description":"Orientações educativas para acessar serviços digitais públicos."}]$json$::jsonb)
  as row(name text, slug text, description text);

create temporary table guido_import_applications on commit drop as
select * from jsonb_to_recordset($json$[{"slug":"banco-demonstracao","category_slug":"servicos-financeiros","name":"Banco — demonstração","description":"Exemplo educativo genérico, sem vínculo com qualquer banco.","status":"draft","is_demo":true},{"slug":"whatsapp","category_slug":"comunicacao","name":"WhatsApp","description":"Mensagens, áudios e chamadas.","status":"published","is_demo":false},{"slug":"gov-br","category_slug":"servicos-publicos","name":"Gov.br","description":"Acesso a serviços digitais do governo.","status":"published","is_demo":false},{"slug":"caixa","category_slug":"servicos-financeiros","name":"Caixa","description":"Serviços do aplicativo bancário.","status":"published","is_demo":false},{"slug":"banco-do-brasil","category_slug":"servicos-financeiros","name":"Banco do Brasil","description":"Serviços do aplicativo bancário.","status":"published","is_demo":false},{"slug":"itau","category_slug":"servicos-financeiros","name":"Itaú","description":"Serviços do aplicativo bancário.","status":"published","is_demo":false},{"slug":"bradesco","category_slug":"servicos-financeiros","name":"Bradesco","description":"Serviços do aplicativo bancário.","status":"published","is_demo":false},{"slug":"santander","category_slug":"servicos-financeiros","name":"Santander","description":"Serviços do aplicativo bancário.","status":"published","is_demo":false},{"slug":"nubank","category_slug":"servicos-financeiros","name":"Nubank","description":"Serviços do aplicativo bancário.","status":"published","is_demo":false},{"slug":"banco-inter","category_slug":"servicos-financeiros","name":"Banco Inter","description":"Serviços do aplicativo bancário.","status":"published","is_demo":false},{"slug":"picpay","category_slug":"servicos-financeiros","name":"PicPay","description":"Serviços da carteira digital.","status":"published","is_demo":false},{"slug":"mercado-pago","category_slug":"servicos-financeiros","name":"Mercado Pago","description":"Serviços da carteira digital.","status":"published","is_demo":false},{"slug":"c6-bank","category_slug":"servicos-financeiros","name":"C6 Bank","description":"Serviços do aplicativo bancário.","status":"published","is_demo":false}]$json$::jsonb)
  as row(slug text, category_slug text, name text, description text,
         status public.guido_publication_status, is_demo boolean);

